{{-- Rendered into broadcasts, so it must carry nothing session-scoped: a CSRF token here would be the POSTER's, delivered to every other member of the room. Turbo sends each viewer's own token as X-CSRF-Token from <meta name="csrf-token">, which RailsCsrf accepts. --}}
<div id="boost_{{ $boost->id }}" class="boost boost-item flex-inline max-width align-center fill-white gap" data-controller="boost-delete" data-boost-delete-perform-class="boost--deleting" data-boost-delete-reveal-class="expanded" data-boost-delete-booster-id-value="{{ $boost->booster_id }}">
<figure class="avatar boost__avatar flex-item-no-shrink"><a class="btn avatar" href="{{ route('users.show', $boost->booster_id, absolute: false) }}" data-turbo-frame="_top"><img src="{{ $boost->booster->avatarUrl() }}" width="48" height="48" alt="{{ $boost->booster->name }} boosted {{ $boost->content }}"></a></figure>
<span role="button" class="txt-small" data-action="click->boost-delete#reveal keydown.enter->boost-delete#reveal:prevent" data-boost-delete-target="content">{{ $boost->content }}</span>
<form action="{{ route('boosts.destroy', ['id' => $boost->message_id, 'boost' => $boost->id], absolute: false) }}" method="post" data-action="boost-delete#perform" data-boost-delete-target="button">@method('DELETE')<button type="submit" class="btn btn--negative boost__delete" aria-label="Delete this boost">−</button></form>
</div>
